package input_guard

import rego.v1

default verdict := {"decision": "allow"}

blocking_signal if {
  input.snapshot.moderation.harm.PromptInjection.detected
}

blocking_signal if {
  input.snapshot.moderation.harm.Hate.severity >= 4
}

verdict := {"decision": "deny", "reason": "unsafe_input"} if {
  blocking_signal
}

